export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-21\",\"workId\":\"xunzi\",\"order\":21,\"title\":\"解蔽\",\"difficulty\":4,\"estimatedMinutes\":13,\"passageIds\":[\"xunzi_ch-21_p-1\",\"xunzi_ch-21_p-2\",\"xunzi_ch-21_p-3\",\"xunzi_ch-21_p-4\",\"xunzi_ch-21_p-5\",\"xunzi_ch-21_p-6\",\"xunzi_ch-21_p-7\",\"xunzi_ch-21_p-8\",\"xunzi_ch-21_p-9\",\"xunzi_ch-21_p-10\",\"xunzi_ch-21_p-11\",\"xunzi_ch-21_p-12\",\"xunzi_ch-21_p-13\",\"xunzi_ch-21_p-14\",\"xunzi_ch-21_p-15\",\"xunzi_ch-21_p-16\",\"xunzi_ch-21_p-17\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-21_p-1\",\"chapterId\":\"xunzi_ch-21\",\"order\":1,\"canonicalText\":\"凡人之患，蔽於一曲，而闇於大理。治則復經，兩疑則惑矣。天下無二道，聖人無兩心。今諸侯異政，百家異說，則必或是或非，或治或亂。亂國之君，亂家之人，此其誠心，莫不求正而以自為也。妒繆於道，而人誘其所迨也。私其所積，唯恐聞其惡也。倚其所私，以觀異術，唯恐聞其美也。是以與治雖走，而是己不輟也。豈不蔽於一曲，而失正求也哉！心不使焉，則白黑在前而目不見，雷鼓在側而耳不聞，況於使者乎？德道之人，亂國之君非之上，亂家之人非之下，豈不哀哉！\",\"sentenceIds\":[\"xunzi_ch-21_p-1_s-1\",\"xunzi_ch-21_p-1_s-2\",\"xunzi_ch-21_p-1_s-3\",\"xunzi_ch-21_p-1_s-4\",\"xunzi_ch-21_p-1_s-5\",\"xunzi_ch-21_p-1_s-6\",\"xunzi_ch-21_p-1_s-7\",\"xunzi_ch-21_p-1_s-8\",\"xunzi_ch-21_p-1_s-9\",\"xunzi_ch-21_p-1_s-10\",\"xunzi_ch-21_p-1_s-11\",\"xunzi_ch-21_p-1_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡人的患，蔽於一曲，而且闇於大理。治則復經，兩疑則惑矣。天下無二道，聖人無兩心。今諸侯異政，百家異說，則必或是或絕不是，或治或亂。亂國的君，亂家的人，此他的誠心，莫不求正而且以自為啊。妒繆於道，而且人誘他的所迨啊。私他的所積，唯恐聞他的惡啊。倚他的所私，以觀異術，唯恐聞他的美啊。是以與治雖走，而且是己不輟啊。豈不蔽於一曲，而且失正求啊哉！心不使焉，則白黑在前而且目不見，雷鼓在側而且耳不聞，況於使的人或事物乎？品德修養道的人，亂國的君絕不是的上，亂家的人絕不是的下，豈不哀哉！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡人之患，蔽於一曲，而闇於大理」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡人之患，蔽於一曲，而闇於大理。治則復經，兩疑則惑矣……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-2\",\"chapterId\":\"xunzi_ch-21\",\"order\":2,\"canonicalText\":\"故為蔽：欲為蔽，惡為蔽，始為蔽，終為蔽，遠為蔽，近為蔽，博為蔽，淺為蔽，古為蔽，今為蔽。凡萬物異則莫不相為蔽，此心術之公患也。\",\"sentenceIds\":[\"xunzi_ch-21_p-2_s-1\",\"xunzi_ch-21_p-2_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以為蔽：欲為蔽，惡為蔽，始為蔽，終為蔽，遠為蔽，近為蔽，博為蔽，淺為蔽，古為蔽，今為蔽。凡萬物異則莫不相為蔽，此心術的公患啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故為蔽：欲為蔽，惡為蔽，始為蔽，終為蔽，遠為蔽，近為蔽，博為蔽，淺為蔽，古為蔽，今為蔽」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故為蔽：欲為蔽，惡為蔽，始為蔽，終為蔽，遠為蔽，近為……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-3\",\"chapterId\":\"xunzi_ch-21\",\"order\":3,\"canonicalText\":\"昔人君之蔽者，夏桀殷紂是也。桀蔽於末喜斯觀，而不知關龍逢，以惑其心，而亂其行。紂蔽於妲己、飛廉，而不知微子啟，以惑其心，而亂其行。故群臣去忠而事私，百姓怨非而不用，賢良退處而隱逃，此其所以喪九牧之地，而虛宗廟之國也。桀死於鬲山，紂縣於赤旆。身不先知，人又莫之諫，此蔽塞之禍也。成湯鑒於夏桀，故主其心而慎治之，是以能長用伊尹，而身不失道，此其所以代夏王而受九有也。文王監於殷紂，故主其心而慎治之，是以能長用呂望，而身不失道，此其所以代殷王而受九牧也。遠方莫不致其珍；故目視備色，耳聽備聲，口食備味，形居備宮，名受備號，生則天下歌，死則四海哭。夫是之謂至盛。《詩》曰：「鳳凰秋秋，其翼若干，其聲若簫。有鳳有凰，樂帝之心。」此不蔽之福也。\",\"sentenceIds\":[\"xunzi_ch-21_p-3_s-1\",\"xunzi_ch-21_p-3_s-2\",\"xunzi_ch-21_p-3_s-3\",\"xunzi_ch-21_p-3_s-4\",\"xunzi_ch-21_p-3_s-5\",\"xunzi_ch-21_p-3_s-6\",\"xunzi_ch-21_p-3_s-7\",\"xunzi_ch-21_p-3_s-8\",\"xunzi_ch-21_p-3_s-9\",\"xunzi_ch-21_p-3_s-10\",\"xunzi_ch-21_p-3_s-11\",\"xunzi_ch-21_p-3_s-12\",\"xunzi_ch-21_p-3_s-13\",\"xunzi_ch-21_p-3_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"昔人君的蔽的人或事物，夏桀殷紂是啊。桀蔽於末喜斯觀，而且不知關龍逢，以惑他的心，而且亂他的行。紂蔽於妲己、飛廉，而且不知微子啟，以惑他的心，而且亂他的行。所以群臣去忠而且事私，百姓怨絕不是而且不用，賢良退處而且隱逃，此他的所以喪九牧的地，而且虛宗廟的國啊。桀死於鬲山，紂縣於赤旆。身不先知，人又莫的諫，此蔽塞的禍啊。成湯鑒於夏桀，所以主他的心而且慎治的，是以能長用伊尹，而且身不失道，此他的所以代夏王而且受九有啊。文王監於殷紂，所以主他的心而且慎治的，是以能長用呂望，而且身不失道，此他的所以代殷王而且受九牧啊。遠方莫不致他的珍；所以目視備色，耳聽備聲，口食備味，形居備宮，名受備號，生則天下歌，死則四海哭。這就是儒家所稱的至盛。《詩》說道：鳳凰秋秋，他的翼若干，他的聲若簫。有鳳有凰，樂帝的心。此不蔽的福啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「昔人君之蔽者，夏桀殷紂是也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「昔人君之蔽者，夏桀殷紂是也。桀蔽於末喜斯觀，而不知關……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-4\",\"chapterId\":\"xunzi_ch-21\",\"order\":4,\"canonicalText\":\"昔人臣之蔽者，唐鞅奚齊是也。唐鞅蔽於欲權而逐載子，奚齊蔽於欲國而罪申生；唐鞅戮於宋，奚齊戮於晉。逐賢相而罪孝兄，身為刑戮，然而不知，此蔽塞之禍也。故以貪鄙、背叛、爭權而不危辱滅亡者，自古及今，未嘗有之也。鮑叔、甯戚、隰朋仁知且不蔽，故能持管仲，而名利福祿與管仲齊。召公、呂望仁知且不蔽，故能持周公而名利福祿與周公齊。傳曰：「知賢之為明，輔賢之謂能，勉之彊之，其福必長。」此之謂也。此不蔽之福也。\",\"sentenceIds\":[\"xunzi_ch-21_p-4_s-1\",\"xunzi_ch-21_p-4_s-2\",\"xunzi_ch-21_p-4_s-3\",\"xunzi_ch-21_p-4_s-4\",\"xunzi_ch-21_p-4_s-5\",\"xunzi_ch-21_p-4_s-6\",\"xunzi_ch-21_p-4_s-7\",\"xunzi_ch-21_p-4_s-8\",\"xunzi_ch-21_p-4_s-9\",\"xunzi_ch-21_p-4_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"昔人臣的蔽的人或事物，唐鞅奚齊是啊。唐鞅蔽於欲權而且逐載子，奚齊蔽於欲國而且罪申生；唐鞅戮於宋，奚齊戮於晉。逐賢相而且罪孝兄，身為刑戮，然而且不知，此蔽塞的禍啊。所以以貪鄙、背叛、爭權而且不危辱滅亡的人或事物，自古及今，未嘗有的啊。鮑叔、甯戚、隰朋仁愛慈悲之德知且不蔽，所以能持管仲，而且名利福祿與管仲齊。召公、呂望仁愛慈悲之德知且不蔽，所以能持周公而且名利福祿與周公齊。傳說道：知賢的為明，輔賢的謂能，勉的彊的，他的福必長。此的謂啊。此不蔽的福啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「昔人臣之蔽者，唐鞅奚齊是也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「昔人臣之蔽者，唐鞅奚齊是也。唐鞅蔽於欲權而逐載子，奚……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-5\",\"chapterId\":\"xunzi_ch-21\",\"order\":5,\"canonicalText\":\"昔賓孟之蔽者，亂家是也。墨子蔽於用而不知文。宋子蔽於欲而不知得。慎子蔽於法而不知賢。申子蔽於埶而不知知。惠子蔽於辭而不知實。莊子蔽於天而不知人。故由用謂之道，盡利矣。由欲謂之道，盡嗛矣。由法謂之道，盡數矣。由埶謂之道，盡便矣。由辭謂之道，盡論矣。由天謂之道，盡因矣。此數具者，皆道之一隅也。夫道者體常而盡變，一隅不足以舉之。曲知之人，觀於道之一隅，而未之能識也。故以為足而飾之，內以自亂，外以惑人，上以蔽下，下以蔽上，此蔽塞之禍也。孔子仁知且不蔽，故學亂術足以為先王者也。一家得周道，舉而用之，不蔽於成積也。故德與周公齊，名與三王並，此不蔽之福也。\",\"sentenceIds\":[\"xunzi_ch-21_p-5_s-1\",\"xunzi_ch-21_p-5_s-2\",\"xunzi_ch-21_p-5_s-3\",\"xunzi_ch-21_p-5_s-4\",\"xunzi_ch-21_p-5_s-5\",\"xunzi_ch-21_p-5_s-6\",\"xunzi_ch-21_p-5_s-7\",\"xunzi_ch-21_p-5_s-8\",\"xunzi_ch-21_p-5_s-9\",\"xunzi_ch-21_p-5_s-10\",\"xunzi_ch-21_p-5_s-11\",\"xunzi_ch-21_p-5_s-12\",\"xunzi_ch-21_p-5_s-13\",\"xunzi_ch-21_p-5_s-14\",\"xunzi_ch-21_p-5_s-15\",\"xunzi_ch-21_p-5_s-16\",\"xunzi_ch-21_p-5_s-17\",\"xunzi_ch-21_p-5_s-18\",\"xunzi_ch-21_p-5_s-19\",\"xunzi_ch-21_p-5_s-20\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"昔賓孟的蔽的人或事物，亂家是啊。墨子蔽於用而且不知文。宋子蔽於欲而且不知得。慎子蔽於國家典章法度而且不知賢。申子蔽於埶而且不知知。惠子蔽於辭而且不知實。莊子蔽於天而且不知人。所以由用謂的道，盡利矣。由欲謂的道，盡嗛矣。由國家典章法度謂的道，盡數矣。由埶謂的道，盡便矣。由辭謂的道，盡論矣。由天謂的道，盡因矣。此數具的人或事物，皆道的一隅啊。夫道的人或事物體常而且盡變，一隅不足以舉的。曲知的人，觀於道的一隅，而且未的能識啊。所以以為足而且飾的，內以自亂，外以惑人，上以蔽下，下以蔽上，此蔽塞的禍啊。孔子仁愛慈悲之德知且不蔽，所以學亂術足以為先王的人或事物啊。一家得周道，舉而且用的，不蔽於成積啊。所以品德修養與周公齊，名與三王並，此不蔽的福啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「昔賓孟之蔽者，亂家是也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「昔賓孟之蔽者，亂家是也。墨子蔽於用而不知文。宋子蔽於……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-6\",\"chapterId\":\"xunzi_ch-21\",\"order\":6,\"canonicalText\":\"聖人知心術之患，見蔽塞之禍，故無欲、無惡、無始、無終、無近、無遠、無博、無淺、無古、無今，兼陳萬物而中縣衡焉。是故眾異不得相蔽以亂其倫也。\",\"sentenceIds\":[\"xunzi_ch-21_p-6_s-1\",\"xunzi_ch-21_p-6_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"聖人知心術的患，見蔽塞的禍，所以無欲、無惡、無始、無終、無近、無遠、無博、無淺、無古、無今，兼陳萬物而且中縣衡焉。正因為如此眾異不得相蔽以亂他的倫啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「聖人知心術之患，見蔽塞之禍，故無欲、無惡、無始、無終、無近、無遠、無博、無淺、無古、無今，兼陳萬物而中縣衡焉」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「聖人知心術之患，見蔽塞之禍，故無欲、無惡、無始、無終……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-7\",\"chapterId\":\"xunzi_ch-21\",\"order\":7,\"canonicalText\":\"何謂衡？曰：道。故心不可以不知道；心不知道，則不可道，而可非道。人孰欲得恣，而守其所不可，以禁其所可？以其不可道之心取人，則必合於不道人，而不合於道人。以其不可道之心與不道人論道人，亂之本也。夫何以知？曰：心知道，然後可道；可道然後守道以禁非道。以其可道之心取人，則合於道人，而不合於不道之人矣。以其可道之心與道人論非道，治之要也。何患不知？故治之要在於知道。\",\"sentenceIds\":[\"xunzi_ch-21_p-7_s-1\",\"xunzi_ch-21_p-7_s-2\",\"xunzi_ch-21_p-7_s-3\",\"xunzi_ch-21_p-7_s-4\",\"xunzi_ch-21_p-7_s-5\",\"xunzi_ch-21_p-7_s-6\",\"xunzi_ch-21_p-7_s-7\",\"xunzi_ch-21_p-7_s-8\",\"xunzi_ch-21_p-7_s-9\",\"xunzi_ch-21_p-7_s-10\",\"xunzi_ch-21_p-7_s-11\",\"xunzi_ch-21_p-7_s-12\",\"xunzi_ch-21_p-7_s-13\",\"xunzi_ch-21_p-7_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"何謂衡？說道：道。所以心不可以不知道；心不知道，則不可道，而且可絕不是道。人孰欲得恣，而且守他的所不可，以禁他的所可？以他的不可道的心取人，則必合於不道人，而且不合於道人。以他的不可道的心與不道人論道人，亂的本啊。夫何以知？說道：心知道，然後可道；可道然後守道以禁絕不是道。以他的可道的心取人，則合於道人，而且不合於不道的人矣。以他的可道的心與道人論絕不是道，治的要啊。何患不知？所以治的要在於知道。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「何謂衡」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「何謂衡？曰：道。故心不可以不知道；心不知道，則不可道……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-8\",\"chapterId\":\"xunzi_ch-21\",\"order\":8,\"canonicalText\":\"人何以知道？曰：心。心何以知？曰：虛壹而靜。心未嘗不臧也，然而有所謂虛；心未嘗不兩也，然而有所謂壹；心未嘗不動也，然而有所謂靜。人生而有知，知而有志；志也者，臧也；然而有所謂虛；不以所已臧害所將受謂之虛。心生而有知，知而有異；異也者，同時兼知之；同時兼知之，兩也；然而有所謂一；不以夫一害此一謂之壹。心臥則夢，偷則自行，使之則謀；故心未嘗不動也；然而有所謂靜；不以夢劇亂知謂之靜。未得道而求道者，謂之虛壹而靜。作之：則將須道者之虛則人，將事道者之壹則盡，盡將思道者靜則察。知道察，知道行，體道者也。虛壹而靜，謂之大清明。萬物莫形而不見，莫見而不論，莫論而失位。坐於室而見四海，處於今而論久遠。疏觀萬物而知其情，參稽治亂而通其度，經緯天地而材官萬物，制割大理而宇宙裡矣。恢恢廣廣，孰知其極？睪睪廣廣，孰知其德？涫涫紛紛，孰知其形？明參日月，大滿八極，夫是之謂大人。夫惡有蔽矣哉！\",\"sentenceIds\":[\"xunzi_ch-21_p-8_s-1\",\"xunzi_ch-21_p-8_s-2\",\"xunzi_ch-21_p-8_s-3\",\"xunzi_ch-21_p-8_s-4\",\"xunzi_ch-21_p-8_s-5\",\"xunzi_ch-21_p-8_s-6\",\"xunzi_ch-21_p-8_s-7\",\"xunzi_ch-21_p-8_s-8\",\"xunzi_ch-21_p-8_s-9\",\"xunzi_ch-21_p-8_s-10\",\"xunzi_ch-21_p-8_s-11\",\"xunzi_ch-21_p-8_s-12\",\"xunzi_ch-21_p-8_s-13\",\"xunzi_ch-21_p-8_s-14\",\"xunzi_ch-21_p-8_s-15\",\"xunzi_ch-21_p-8_s-16\",\"xunzi_ch-21_p-8_s-17\",\"xunzi_ch-21_p-8_s-18\",\"xunzi_ch-21_p-8_s-19\",\"xunzi_ch-21_p-8_s-20\",\"xunzi_ch-21_p-8_s-21\",\"xunzi_ch-21_p-8_s-22\",\"xunzi_ch-21_p-8_s-23\",\"xunzi_ch-21_p-8_s-24\",\"xunzi_ch-21_p-8_s-25\",\"xunzi_ch-21_p-8_s-26\",\"xunzi_ch-21_p-8_s-27\",\"xunzi_ch-21_p-8_s-28\",\"xunzi_ch-21_p-8_s-29\",\"xunzi_ch-21_p-8_s-30\",\"xunzi_ch-21_p-8_s-31\",\"xunzi_ch-21_p-8_s-32\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"人何以知道？說道：心。心何以知？說道：虛壹而且靜。心未嘗不臧啊，然而且有所謂虛；心未嘗不兩啊，然而且有所謂壹；心未嘗不動啊，然而且有所謂靜。人生而且有知，知而且有志；志啊的人或事物，臧啊；然而且有所謂虛；不以所已臧害所將受謂的虛。心生而且有知，知而且有異；異啊的人或事物，同時兼知的；同時兼知的，兩啊；然而且有所謂一；不以夫一害此一謂的壹。心臥則夢，偷則自行，使的則謀；所以心未嘗不動啊；然而且有所謂靜；不以夢劇亂知謂的靜。未得道而且求道的人或事物，謂的虛壹而且靜。作的：則將須道的人或事物的虛則人，將事道的人或事物的壹則盡，盡將思道的人或事物靜則察。知道察，知道行，體道的人或事物啊。虛壹而且靜，謂的大清明。萬物莫形而且不見，莫見而且不論，莫論而且失位。坐於室而且見四海，處於今而且論久遠。疏觀萬物而且知他的情，參稽治亂而且通他的度，經緯天地而且材官萬物，制割大理而且宇宙裡矣。恢恢廣廣，孰知他的極？睪睪廣廣，孰知他的品德修養？涫涫紛紛，孰知他的形？明參日月，大滿八極，這就是儒家所稱的大人。夫惡有蔽矣哉！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「人何以知道」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「人何以知道？曰：心。心何以知？曰：虛壹而靜。心未嘗不……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-9\",\"chapterId\":\"xunzi_ch-21\",\"order\":9,\"canonicalText\":\"心者，形之君也，而神明之主也，出令而無所受令。自禁也，自使也，自奪也，自取也，自行也，自止也。故口可劫而使墨雲，形可劫而使詘申，心不可劫而使易意，是之則受，非之則辭。故曰：心容，其擇也無禁，必自現，其物也雜博，其情之至也不貳。《詩》雲：「采采卷耳，不盈傾筐。嗟我懷人，寘彼周行。」傾筐易滿也，卷耳易得也，然而不可以貳周行。故曰：心枝則無知，傾則不精，貳則疑惑。以贊稽之，萬物可兼知也。身盡其故則美。類不可兩也，故知者擇一而壹焉。\",\"sentenceIds\":[\"xunzi_ch-21_p-9_s-1\",\"xunzi_ch-21_p-9_s-2\",\"xunzi_ch-21_p-9_s-3\",\"xunzi_ch-21_p-9_s-4\",\"xunzi_ch-21_p-9_s-5\",\"xunzi_ch-21_p-9_s-6\",\"xunzi_ch-21_p-9_s-7\",\"xunzi_ch-21_p-9_s-8\",\"xunzi_ch-21_p-9_s-9\",\"xunzi_ch-21_p-9_s-10\",\"xunzi_ch-21_p-9_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"心的人或事物，形的君啊，而且神明的主啊，出令而且無所受令。自禁啊，自使啊，自奪啊，自取啊，自行啊，自止啊。所以口可劫而且使墨雲，形可劫而且使詘申，心不可劫而且使易意，是的則受，絕不是的則辭。所以古聖先賢說道：心容，他的擇啊無禁，必自現，他的物啊雜博，他的情的至啊不貳。《詩》雲：采采卷耳，不盈傾筐。嗟我懷人，寘彼周行。傾筐易滿啊，卷耳易得啊，然而且不可以貳周行。所以古聖先賢說道：心枝則無知，傾則不精，貳則疑惑。以贊稽的，萬物可兼知啊。身盡他的所以則美。類不可兩啊，所以知的人或事物擇一而且壹焉。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「心者，形之君也，而神明之主也，出令而無所受令」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「心者，形之君也，而神明之主也，出令而無所受令。自禁也……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-10\",\"chapterId\":\"xunzi_ch-21\",\"order\":10,\"canonicalText\":\"農精於田，而不可以為田師；賈精於市，而不可以為市師；工精於器，而不可以為器師。有人也，不能此三技，而可使治三官。曰：精於道者也。精於物者也。精於物者以物物，精於道者兼物物。故君子壹於道，而以贊稽物。壹於道則正，以贊稽物則察；以正志行察論，則萬物官矣。昔者舜之治天下也，不以事詔而萬物成。處一危之，其榮滿側；養一之微，榮矣而未知。故道經曰：「人心之危，道心之微。」危微之幾，惟明君子而後能知之。故人心譬如槃水，正錯而勿動，則湛濁在下，而清明在上，則足以見鬒眉而察理矣。微風過之，湛濁動乎下，清明亂於上，則不可以得大形之正也。心亦如是矣。故導之以理，養之以清，物莫之傾，則足以定是非決嫌疑矣。小物引之，則其正外易，其心內傾，則不足以決麤理矣。故好書者眾矣，而倉頡獨傳者，壹也；好稼者眾矣，而后稷獨傳者，壹也。好樂者眾矣，而夔獨傳者，壹也；好義者眾矣，而舜獨傳者，壹也。倕作弓，浮游作矢，而羿精於射；奚仲作車，乘杜作乘馬，而造父精於御：自古及今，未嘗有兩而能精者也。曾子曰：「是其庭可以搏鼠，惡能與我歌矣！」\",\"sentenceIds\":[\"xunzi_ch-21_p-10_s-1\",\"xunzi_ch-21_p-10_s-2\",\"xunzi_ch-21_p-10_s-3\",\"xunzi_ch-21_p-10_s-4\",\"xunzi_ch-21_p-10_s-5\",\"xunzi_ch-21_p-10_s-6\",\"xunzi_ch-21_p-10_s-7\",\"xunzi_ch-21_p-10_s-8\",\"xunzi_ch-21_p-10_s-9\",\"xunzi_ch-21_p-10_s-10\",\"xunzi_ch-21_p-10_s-11\",\"xunzi_ch-21_p-10_s-12\",\"xunzi_ch-21_p-10_s-13\",\"xunzi_ch-21_p-10_s-14\",\"xunzi_ch-21_p-10_s-15\",\"xunzi_ch-21_p-10_s-16\",\"xunzi_ch-21_p-10_s-17\",\"xunzi_ch-21_p-10_s-18\",\"xunzi_ch-21_p-10_s-19\",\"xunzi_ch-21_p-10_s-20\",\"xunzi_ch-21_p-10_s-21\",\"xunzi_ch-21_p-10_s-22\",\"xunzi_ch-21_p-10_s-23\",\"xunzi_ch-21_p-10_s-24\",\"xunzi_ch-21_p-10_s-25\",\"xunzi_ch-21_p-10_s-26\",\"xunzi_ch-21_p-10_s-27\",\"xunzi_ch-21_p-10_s-28\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"農精於田，而且不可以為田師；賈精於市，而且不可以為市師；工精於器，而且不可以為器師。有人啊，不能此三技，而且可使治三官。說道：精於道的人或事物啊。精於物的人或事物啊。精於物的人或事物以物物，精於道的人或事物兼物物。所以君子壹於道，而且以贊稽物。壹於道則正，以贊稽物則察；以正志行察論，則萬物官矣。昔的人或事物舜的治天下啊，不以事詔而且萬物成。處一危的，他的榮滿側；養一的微，榮矣而且未知。所以道經說道：人心的危，道心的微。危微的幾，惟明君子而且後能知的。所以人心譬如槃水，正錯而且勿動，則湛濁在下，而且清明在上，則足以見鬒眉而且察理矣。微風過的，湛濁動乎下，清明亂於上，則不可以得大形的正啊。心亦如是矣。所以導的以理，養的以清，物莫的傾，則足以定是絕不是決嫌疑矣。小物引的，則他的正外易，他的心內傾，則不足以決麤理矣。所以好書的人或事物眾矣，而且倉頡獨傳的人或事物，壹啊；好稼的人或事物眾矣，而且后稷獨傳的人或事物，壹啊。好樂的人或事物眾矣，而且夔獨傳的人或事物，壹啊；好正義道義的人或事物眾矣，而且舜獨傳的人或事物，壹啊。倕作弓，浮游作矢，而且羿精於射；奚仲作車，乘杜作乘馬，而且造父精於御：自古及今，未嘗有兩而且能精的人或事物啊。曾子說道：是他的庭可以搏鼠，惡能與我歌矣！\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「農精於田，而不可以為田師」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「農精於田，而不可以為田師；賈精於市，而不可以為市師；……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-11\",\"chapterId\":\"xunzi_ch-21\",\"order\":11,\"canonicalText\":\"空石之中有人焉，其名曰觙。其為人也，善射以好思。耳目之欲接，則敗其思；蚊虻之聲聞，則挫其精。是以闢耳目之欲，而遠蚊虻之聲，閑居靜思則通。思仁若是，可謂微乎？孟子惡敗而出妻，可謂能自彊矣；有子惡臥而焠掌，可謂能自忍矣；未及好也。闢耳目之慾，可謂自彊矣，未及思也。蚊虻之聲聞則挫其精，可謂危矣；未可謂微也。夫微者，至人也。至人也，何彊？何忍？何危？故濁明外景，清明內景，聖人縱其欲，兼其情，而制焉者理矣。夫何彊？何忍？何危？故仁者之行道也，無為也；聖人之行道也，無彊也。仁者之思也恭，聖者之思也樂。此治心之道也。\",\"sentenceIds\":[\"xunzi_ch-21_p-11_s-1\",\"xunzi_ch-21_p-11_s-2\",\"xunzi_ch-21_p-11_s-3\",\"xunzi_ch-21_p-11_s-4\",\"xunzi_ch-21_p-11_s-5\",\"xunzi_ch-21_p-11_s-6\",\"xunzi_ch-21_p-11_s-7\",\"xunzi_ch-21_p-11_s-8\",\"xunzi_ch-21_p-11_s-9\",\"xunzi_ch-21_p-11_s-10\",\"xunzi_ch-21_p-11_s-11\",\"xunzi_ch-21_p-11_s-12\",\"xunzi_ch-21_p-11_s-13\",\"xunzi_ch-21_p-11_s-14\",\"xunzi_ch-21_p-11_s-15\",\"xunzi_ch-21_p-11_s-16\",\"xunzi_ch-21_p-11_s-17\",\"xunzi_ch-21_p-11_s-18\",\"xunzi_ch-21_p-11_s-19\",\"xunzi_ch-21_p-11_s-20\",\"xunzi_ch-21_p-11_s-21\",\"xunzi_ch-21_p-11_s-22\",\"xunzi_ch-21_p-11_s-23\",\"xunzi_ch-21_p-11_s-24\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"空石的中有人焉，他的名說道：觙。他的為人啊，善射以好思。耳目的欲接，則敗他的思；蚊虻的聲聞，則挫他的精。是以闢耳目的欲，而且遠蚊虻的聲，閑居靜思則通。思仁愛慈悲之德若是，可謂微乎？孟子惡敗而且出妻，可謂能自彊矣；有子惡臥而且焠掌，可謂能自忍矣；未及好啊。闢耳目的慾，可謂自彊矣，未及思啊。蚊虻的聲聞則挫他的精，可謂危矣；未可謂微啊。夫微的人或事物，至人啊。至人啊，何彊？何忍？何危？所以濁明外景，清明內景，聖人縱他的欲，兼他的情，而且制焉的人或事物理矣。夫何彊？所以仁愛慈悲之德的人或事物的行道啊，無為啊；聖人的行道啊，無彊啊。仁愛慈悲之德的人或事物的思啊恭，聖的人或事物的思啊樂。此治心的道啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「空石之中有人焉，其名曰觙」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「空石之中有人焉，其名曰觙。其為人也，善射以好思。耳目……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-12\",\"chapterId\":\"xunzi_ch-21\",\"order\":12,\"canonicalText\":\"凡觀物有疑，中心不定，則外物不清。吾慮不清，未可定然否也。冥冥而行者，見寢石以為伏虎也，見植林以為後人也：冥冥蔽其明也。醉者越百步之溝，以為蹞步之澮也；俯而出城門，以為小之閨也：酒亂其神也。厭目而視者，視一為兩；掩耳而聽者，聽漠漠而以為哅哅：埶亂其官也。故從山上望牛者若羊，而求羊者不下牽也：遠蔽其大也。從山下望木者，十仞之木若箸，而求箸者不上折也：高蔽其長也。水動而景搖，人不以定美惡：水埶玄也。瞽者仰視而不見星，人不以定有無：用精惑也。有人焉以此時定物，則世之愚者也。彼愚者之定物，以疑決疑，決必不當。夫苟不當，安能無過乎？\",\"sentenceIds\":[\"xunzi_ch-21_p-12_s-1\",\"xunzi_ch-21_p-12_s-2\",\"xunzi_ch-21_p-12_s-3\",\"xunzi_ch-21_p-12_s-4\",\"xunzi_ch-21_p-12_s-5\",\"xunzi_ch-21_p-12_s-6\",\"xunzi_ch-21_p-12_s-7\",\"xunzi_ch-21_p-12_s-8\",\"xunzi_ch-21_p-12_s-9\",\"xunzi_ch-21_p-12_s-10\",\"xunzi_ch-21_p-12_s-11\",\"xunzi_ch-21_p-12_s-12\",\"xunzi_ch-21_p-12_s-13\",\"xunzi_ch-21_p-12_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡觀物有疑，中心不定，則外物不清。吾慮不清，未可定然否啊。冥冥而且行的人或事物，見寢石以為伏虎啊，見植林以為後人啊：冥冥蔽他的明啊。醉的人或事物越百步的溝，以為蹞步的澮啊；俯而且出城門，以為小的閨啊：酒亂他的神啊。厭目而且視的人或事物，視一為兩；掩耳而且聽的人或事物，聽漠漠而且以為哅哅：埶亂他的官啊。所以從山上望牛的人或事物若羊，而且求羊的人或事物不下牽啊：遠蔽他的大啊。從山下望木的人或事物，十仞的木若箸，而且求箸的人或事物不上折啊：高蔽他的長啊。水動而且景搖，人不以定美惡：水埶玄啊。瞽的人或事物仰視而且不見星，人不以定有無：用精惑啊。有人焉以此時定物，則世的愚的人或事物啊。彼愚的人或事物的定物，以疑決疑，決必不當。夫苟不當，安能無過乎？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡觀物有疑，中心不定，則外物不清」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡觀物有疑，中心不定，則外物不清。吾慮不清，未可定然……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-13\",\"chapterId\":\"xunzi_ch-21\",\"order\":13,\"canonicalText\":\"夏首之南有人焉；曰涓蜀梁。其為人也，愚而善畏。明月而宵行，俯見其影，以為伏鬼也；仰視其髮，以為立魅也。背而走，比至其家，失氣而死。豈不哀哉！凡人之有鬼也，必以其感忽之間，疑玄之時定1之。此人之所以無有而有無之時也，而己以定事。故傷於濕而痺，痺而擊鼓烹豚，則必有敝鼓喪豚之費矣，而未有俞疾之福也。故雖不在夏首之南，則無以異矣。\",\"sentenceIds\":[\"xunzi_ch-21_p-13_s-1\",\"xunzi_ch-21_p-13_s-2\",\"xunzi_ch-21_p-13_s-3\",\"xunzi_ch-21_p-13_s-4\",\"xunzi_ch-21_p-13_s-5\",\"xunzi_ch-21_p-13_s-6\",\"xunzi_ch-21_p-13_s-7\",\"xunzi_ch-21_p-13_s-8\",\"xunzi_ch-21_p-13_s-9\",\"xunzi_ch-21_p-13_s-10\",\"xunzi_ch-21_p-13_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夏首的南有人焉；說道：涓蜀梁。他的為人啊，愚而且善畏。明月而且宵行，俯見他的影，以為伏鬼啊；仰視他的髮，以為立魅啊。背而且走，比至他的家，失氣而且死。豈不哀哉！凡人的有鬼啊，必以他的感忽的間，疑玄的時定1的。此人的所以無有而且有無的時啊，而且己以定事。所以傷於濕而且痺，痺而且擊鼓烹豚，則必有敝鼓喪豚的費矣，而且未有俞疾的福啊。所以雖不在夏首的南，則無以異矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「夏首之南有人焉」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「夏首之南有人焉；曰涓蜀梁。其為人也，愚而善畏。明月而……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-14\",\"chapterId\":\"xunzi_ch-21\",\"order\":14,\"canonicalText\":\"凡以知，人之性也；可以知，物之理也。以可以知人之性，求可以知物之理，而無所疑止之，則沒世窮年不能徧也。其所以貫理焉雖億萬，已不足浹萬物之變，與愚者若一。學、老身長子，而與愚者若一，猶不知錯，夫是之謂妄人。故學也者，固學止之也。惡乎止之？曰：止諸至足。曷謂至足？曰：聖王。聖也者，盡倫者也；王也者，盡制者也；兩盡者，足以為天下極矣。故學者以聖王為師，案以聖王之制為法，法其法以求其統類，以務象效其人。嚮是而務，士也；類是而幾，君子也；知之，聖人也。故有知非以慮是，則謂之懼；有勇非以持是，則謂之賊；察孰非以分是，則謂之篡；多能非以脩蕩是，則謂之知；辯利非以言是，則謂之詍。傳曰：「天下有二：非察是，是察非。」謂合王制不合王制也。天下有不以是為隆正也，然而猶有能分是非、治曲直者邪？\",\"sentenceIds\":[\"xunzi_ch-21_p-14_s-1\",\"xunzi_ch-21_p-14_s-2\",\"xunzi_ch-21_p-14_s-3\",\"xunzi_ch-21_p-14_s-4\",\"xunzi_ch-21_p-14_s-5\",\"xunzi_ch-21_p-14_s-6\",\"xunzi_ch-21_p-14_s-7\",\"xunzi_ch-21_p-14_s-8\",\"xunzi_ch-21_p-14_s-9\",\"xunzi_ch-21_p-14_s-10\",\"xunzi_ch-21_p-14_s-11\",\"xunzi_ch-21_p-14_s-12\",\"xunzi_ch-21_p-14_s-13\",\"xunzi_ch-21_p-14_s-14\",\"xunzi_ch-21_p-14_s-15\",\"xunzi_ch-21_p-14_s-16\",\"xunzi_ch-21_p-14_s-17\",\"xunzi_ch-21_p-14_s-18\",\"xunzi_ch-21_p-14_s-19\",\"xunzi_ch-21_p-14_s-20\",\"xunzi_ch-21_p-14_s-21\",\"xunzi_ch-21_p-14_s-22\",\"xunzi_ch-21_p-14_s-23\",\"xunzi_ch-21_p-14_s-24\",\"xunzi_ch-21_p-14_s-25\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡以知，人的性啊；可以知，物的理啊。以可以知人的性，求可以知物的理，而且無所疑止的，則沒世窮年不能徧啊。他的所以貫理焉雖億萬，已不足浹萬物的變，與愚的人或事物若一。學、老身長子，而且與愚的人或事物若一，猶不知錯，這就是儒家所稱的妄人。所以學啊的人或事物，固學止的啊。惡乎止的？說道：止諸至足。曷謂至足？說道：聖王。聖啊的人或事物，盡倫的人或事物啊；王啊的人或事物，盡制的人或事物啊；兩盡的人或事物，足以為天下極矣。所以學的人或事物以聖王為師，案以聖王的制為國家典章法度，國家典章法度他的國家典章法度以求他的統類，以務象效他的人。嚮是而且務，士啊；類是而且幾，君子啊；知的，聖人啊。所以有知絕不是以慮是，則謂的懼；有勇絕不是以持是，則謂的賊；察孰絕不是以分是，則謂的篡；多能絕不是以脩蕩是，則謂的知；辯利絕不是以言是，則謂的詍。傳說道：天下有二：絕不是察是，是察絕不是。謂合王制不合王制啊。天下有不以是為隆正啊，然而且猶有能分是絕不是、治曲直的人或事物邪？\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡以知，人之性也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡以知，人之性也；可以知，物之理也。以可以知人之性，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-15\",\"chapterId\":\"xunzi_ch-21\",\"order\":15,\"canonicalText\":\"若夫非分是非，非治曲直，非辨治亂，非治人道，雖能之無益於人，不能無損於人；案直將治怪說，玩奇辭，以相撓滑也；案彊鉗而利口，厚顏而忍詬，無正而恣睢，妄辨而幾利；不好辭讓，不敬禮節，而好相推擠：此亂世姦人之說也，則天下之治說者，方多然矣。傳曰：「析辭而為察，言物而為辨，君子賤之。博聞彊志，不合王制，君子賤之。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-21_p-15_s-1\",\"xunzi_ch-21_p-15_s-2\",\"xunzi_ch-21_p-15_s-3\",\"xunzi_ch-21_p-15_s-4\",\"xunzi_ch-21_p-15_s-5\",\"xunzi_ch-21_p-15_s-6\",\"xunzi_ch-21_p-15_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"至於談到那絕不是分是絕不是，絕不是治曲直，絕不是辨治亂，絕不是治人道，雖能的無益於人，不能無損於人；案直將治怪說，玩奇辭，以相撓滑啊；案彊鉗而且利口，厚顏而且忍詬，無正而且恣睢，妄辨而且幾利；不好辭讓，不敬禮正義道義道品德修養規程節，而且好相推擠：此亂世姦人的說啊，則天下的治說的人或事物，方多然矣。傳說道：析辭而且為察，言物而且為辨，君子賤的。博聞彊志，不合王制，君子賤的。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「若夫非分是非，非治曲直，非辨治亂，非治人道，雖能之無益於人，不能無損於人」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「若夫非分是非，非治曲直，非辨治亂，非治人道，雖能之無……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-16\",\"chapterId\":\"xunzi_ch-21\",\"order\":16,\"canonicalText\":\"為之無益於成也，求之無益於得也，憂戚之無益於幾也，則廣焉能棄之矣，不以自妨也，不少頃幹之胸中。不慕往，不閔來，無邑憐之心，當時則動，物至而應，事起而辨，治亂可否，昭然明矣。\",\"sentenceIds\":[\"xunzi_ch-21_p-16_s-1\",\"xunzi_ch-21_p-16_s-2\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"為的無益於成啊，求的無益於得啊，憂戚的無益於幾啊，則廣焉能棄的矣，不以自妨啊，不少頃幹的胸中。不慕往，不閔來，無邑憐的心，當時則動，物至而且應，事起而且辨，治亂可否，昭然明矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「為之無益於成也，求之無益於得也，憂戚之無益於幾也，則廣焉能棄之矣，不以自妨也，不少頃幹之胸中」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「為之無益於成也，求之無益於得也，憂戚之無益於幾也，則……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-21_p-17\",\"chapterId\":\"xunzi_ch-21\",\"order\":17,\"canonicalText\":\"周而成，泄而敗，明君無之有也。宣而成，隱而敗，闇君無之有也。故人君者，周則讒言至矣，直言反矣；小人邇而君子遠矣！《詩》雲：「墨以為明，狐狸而蒼。」此言上幽而下險也。君人者，宣則直言至矣，而讒言反矣；君子邇而小人遠矣！《詩》雲：「明明在下，赫赫在上。」此言上明而下化也。\",\"sentenceIds\":[\"xunzi_ch-21_p-17_s-1\",\"xunzi_ch-21_p-17_s-2\",\"xunzi_ch-21_p-17_s-3\",\"xunzi_ch-21_p-17_s-4\",\"xunzi_ch-21_p-17_s-5\",\"xunzi_ch-21_p-17_s-6\",\"xunzi_ch-21_p-17_s-7\",\"xunzi_ch-21_p-17_s-8\",\"xunzi_ch-21_p-17_s-9\",\"xunzi_ch-21_p-17_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"周而且成，泄而且敗，明君無的有啊。宣而且成，隱而且敗，闇君無的有啊。所以人君的人或事物，周則讒言至矣，直言反矣；小人邇而且君子遠矣！《詩》雲：墨以為明，狐狸而且蒼。此言上幽而且下險啊。君人的人或事物，宣則直言至矣，而且讒言反矣；君子邇而且小人遠矣！《詩》雲：明明在下，赫赫在上。此言上明而且下化啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈解蔽〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「周而成，泄而敗，明君無之有也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「周而成，泄而敗，明君無之有也。宣而成，隱而敗，闇君無……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-21_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":1,\"canonicalText\":\"凡人之患，蔽於一曲，而闇於大理。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":2,\"canonicalText\":\"治則復經，兩疑則惑矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":3,\"canonicalText\":\"天下無二道，聖人無兩心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":4,\"canonicalText\":\"今諸侯異政，百家異說，則必或是或非，或治或亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":5,\"canonicalText\":\"亂國之君，亂家之人，此其誠心，莫不求正而以自為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":6,\"canonicalText\":\"妒繆於道，而人誘其所迨也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":7,\"canonicalText\":\"私其所積，唯恐聞其惡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":8,\"canonicalText\":\"倚其所私，以觀異術，唯恐聞其美也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":9,\"canonicalText\":\"是以與治雖走，而是己不輟也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":10,\"canonicalText\":\"豈不蔽於一曲，而失正求也哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":11,\"canonicalText\":\"心不使焉，則白黑在前而目不見，雷鼓在側而耳不聞，況於使者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-1_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-1\",\"order\":12,\"canonicalText\":\"德道之人，亂國之君非之上，亂家之人非之下，豈不哀哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-2\",\"order\":1,\"canonicalText\":\"故為蔽：欲為蔽，惡為蔽，始為蔽，終為蔽，遠為蔽，近為蔽，博為蔽，淺為蔽，古為蔽，今為蔽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-2_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-2\",\"order\":2,\"canonicalText\":\"凡萬物異則莫不相為蔽，此心術之公患也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":1,\"canonicalText\":\"昔人君之蔽者，夏桀殷紂是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":2,\"canonicalText\":\"桀蔽於末喜斯觀，而不知關龍逢，以惑其心，而亂其行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":3,\"canonicalText\":\"紂蔽於妲己、飛廉，而不知微子啟，以惑其心，而亂其行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":4,\"canonicalText\":\"故群臣去忠而事私，百姓怨非而不用，賢良退處而隱逃，此其所以喪九牧之地，而虛宗廟之國也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":5,\"canonicalText\":\"桀死於鬲山，紂縣於赤旆。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":6,\"canonicalText\":\"身不先知，人又莫之諫，此蔽塞之禍也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":7,\"canonicalText\":\"成湯鑒於夏桀，故主其心而慎治之，是以能長用伊尹，而身不失道，此其所以代夏王而受九有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":8,\"canonicalText\":\"文王監於殷紂，故主其心而慎治之，是以能長用呂望，而身不失道，此其所以代殷王而受九牧也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":9,\"canonicalText\":\"遠方莫不致其珍；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":10,\"canonicalText\":\"故目視備色，耳聽備聲，口食備味，形居備宮，名受備號，生則天下歌，死則四海哭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":11,\"canonicalText\":\"夫是之謂至盛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":12,\"canonicalText\":\"《詩》曰：「鳳凰秋秋，其翼若干，其聲若簫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":13,\"canonicalText\":\"有鳳有凰，樂帝之心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-3_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-3\",\"order\":14,\"canonicalText\":\"」此不蔽之福也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":1,\"canonicalText\":\"昔人臣之蔽者，唐鞅奚齊是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":2,\"canonicalText\":\"唐鞅蔽於欲權而逐載子，奚齊蔽於欲國而罪申生；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":3,\"canonicalText\":\"唐鞅戮於宋，奚齊戮於晉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":4,\"canonicalText\":\"逐賢相而罪孝兄，身為刑戮，然而不知，此蔽塞之禍也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":5,\"canonicalText\":\"故以貪鄙、背叛、爭權而不危辱滅亡者，自古及今，未嘗有之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":6,\"canonicalText\":\"鮑叔、甯戚、隰朋仁知且不蔽，故能持管仲，而名利福祿與管仲齊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":7,\"canonicalText\":\"召公、呂望仁知且不蔽，故能持周公而名利福祿與周公齊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":8,\"canonicalText\":\"傳曰：「知賢之為明，輔賢之謂能，勉之彊之，其福必長。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":9,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-4_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-4\",\"order\":10,\"canonicalText\":\"此不蔽之福也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":1,\"canonicalText\":\"昔賓孟之蔽者，亂家是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":2,\"canonicalText\":\"墨子蔽於用而不知文。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":3,\"canonicalText\":\"宋子蔽於欲而不知得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":4,\"canonicalText\":\"慎子蔽於法而不知賢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":5,\"canonicalText\":\"申子蔽於埶而不知知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":6,\"canonicalText\":\"惠子蔽於辭而不知實。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":7,\"canonicalText\":\"莊子蔽於天而不知人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":8,\"canonicalText\":\"故由用謂之道，盡利矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":9,\"canonicalText\":\"由欲謂之道，盡嗛矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":10,\"canonicalText\":\"由法謂之道，盡數矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":11,\"canonicalText\":\"由埶謂之道，盡便矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":12,\"canonicalText\":\"由辭謂之道，盡論矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":13,\"canonicalText\":\"由天謂之道，盡因矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":14,\"canonicalText\":\"此數具者，皆道之一隅也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":15,\"canonicalText\":\"夫道者體常而盡變，一隅不足以舉之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":16,\"canonicalText\":\"曲知之人，觀於道之一隅，而未之能識也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":17,\"canonicalText\":\"故以為足而飾之，內以自亂，外以惑人，上以蔽下，下以蔽上，此蔽塞之禍也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":18,\"canonicalText\":\"孔子仁知且不蔽，故學亂術足以為先王者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":19,\"canonicalText\":\"一家得周道，舉而用之，不蔽於成積也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-5_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-5\",\"order\":20,\"canonicalText\":\"故德與周公齊，名與三王並，此不蔽之福也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-6\",\"order\":1,\"canonicalText\":\"聖人知心術之患，見蔽塞之禍，故無欲、無惡、無始、無終、無近、無遠、無博、無淺、無古、無今，兼陳萬物而中縣衡焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-6\",\"order\":2,\"canonicalText\":\"是故眾異不得相蔽以亂其倫也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":1,\"canonicalText\":\"何謂衡？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":2,\"canonicalText\":\"曰：道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":3,\"canonicalText\":\"故心不可以不知道；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":4,\"canonicalText\":\"心不知道，則不可道，而可非道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":5,\"canonicalText\":\"人孰欲得恣，而守其所不可，以禁其所可？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":6,\"canonicalText\":\"以其不可道之心取人，則必合於不道人，而不合於道人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":7,\"canonicalText\":\"以其不可道之心與不道人論道人，亂之本也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":8,\"canonicalText\":\"夫何以知？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":9,\"canonicalText\":\"曰：心知道，然後可道；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":10,\"canonicalText\":\"可道然後守道以禁非道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":11,\"canonicalText\":\"以其可道之心取人，則合於道人，而不合於不道之人矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":12,\"canonicalText\":\"以其可道之心與道人論非道，治之要也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":13,\"canonicalText\":\"何患不知？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-7_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-7\",\"order\":14,\"canonicalText\":\"故治之要在於知道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":1,\"canonicalText\":\"人何以知道？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":2,\"canonicalText\":\"曰：心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":3,\"canonicalText\":\"心何以知？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":4,\"canonicalText\":\"曰：虛壹而靜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":5,\"canonicalText\":\"心未嘗不臧也，然而有所謂虛；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":6,\"canonicalText\":\"心未嘗不兩也，然而有所謂壹；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":7,\"canonicalText\":\"心未嘗不動也，然而有所謂靜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":8,\"canonicalText\":\"人生而有知，知而有志；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":9,\"canonicalText\":\"志也者，臧也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":10,\"canonicalText\":\"然而有所謂虛；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":11,\"canonicalText\":\"不以所已臧害所將受謂之虛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":12,\"canonicalText\":\"心生而有知，知而有異；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":13,\"canonicalText\":\"異也者，同時兼知之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":14,\"canonicalText\":\"同時兼知之，兩也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":15,\"canonicalText\":\"然而有所謂一；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":16,\"canonicalText\":\"不以夫一害此一謂之壹。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":17,\"canonicalText\":\"心臥則夢，偷則自行，使之則謀；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":18,\"canonicalText\":\"故心未嘗不動也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":19,\"canonicalText\":\"然而有所謂靜；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":20,\"canonicalText\":\"不以夢劇亂知謂之靜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":21,\"canonicalText\":\"未得道而求道者，謂之虛壹而靜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":22,\"canonicalText\":\"作之：則將須道者之虛則人，將事道者之壹則盡，盡將思道者靜則察。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":23,\"canonicalText\":\"知道察，知道行，體道者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":24,\"canonicalText\":\"虛壹而靜，謂之大清明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":25,\"canonicalText\":\"萬物莫形而不見，莫見而不論，莫論而失位。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":26,\"canonicalText\":\"坐於室而見四海，處於今而論久遠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":27,\"canonicalText\":\"疏觀萬物而知其情，參稽治亂而通其度，經緯天地而材官萬物，制割大理而宇宙裡矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":28,\"canonicalText\":\"恢恢廣廣，孰知其極？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-29\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":29,\"canonicalText\":\"睪睪廣廣，孰知其德？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-30\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":30,\"canonicalText\":\"涫涫紛紛，孰知其形？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-31\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":31,\"canonicalText\":\"明參日月，大滿八極，夫是之謂大人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-8_s-32\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-8\",\"order\":32,\"canonicalText\":\"夫惡有蔽矣哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":1,\"canonicalText\":\"心者，形之君也，而神明之主也，出令而無所受令。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":2,\"canonicalText\":\"自禁也，自使也，自奪也，自取也，自行也，自止也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":3,\"canonicalText\":\"故口可劫而使墨雲，形可劫而使詘申，心不可劫而使易意，是之則受，非之則辭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":4,\"canonicalText\":\"故曰：心容，其擇也無禁，必自現，其物也雜博，其情之至也不貳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":5,\"canonicalText\":\"《詩》雲：「采采卷耳，不盈傾筐。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":6,\"canonicalText\":\"嗟我懷人，寘彼周行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":7,\"canonicalText\":\"」傾筐易滿也，卷耳易得也，然而不可以貳周行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":8,\"canonicalText\":\"故曰：心枝則無知，傾則不精，貳則疑惑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":9,\"canonicalText\":\"以贊稽之，萬物可兼知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":10,\"canonicalText\":\"身盡其故則美。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-9_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-9\",\"order\":11,\"canonicalText\":\"類不可兩也，故知者擇一而壹焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":1,\"canonicalText\":\"農精於田，而不可以為田師；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":2,\"canonicalText\":\"賈精於市，而不可以為市師；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":3,\"canonicalText\":\"工精於器，而不可以為器師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":4,\"canonicalText\":\"有人也，不能此三技，而可使治三官。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":5,\"canonicalText\":\"曰：精於道者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":6,\"canonicalText\":\"精於物者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":7,\"canonicalText\":\"精於物者以物物，精於道者兼物物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":8,\"canonicalText\":\"故君子壹於道，而以贊稽物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":9,\"canonicalText\":\"壹於道則正，以贊稽物則察；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":10,\"canonicalText\":\"以正志行察論，則萬物官矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":11,\"canonicalText\":\"昔者舜之治天下也，不以事詔而萬物成。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":12,\"canonicalText\":\"處一危之，其榮滿側；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":13,\"canonicalText\":\"養一之微，榮矣而未知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":14,\"canonicalText\":\"故道經曰：「人心之危，道心之微。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":15,\"canonicalText\":\"」危微之幾，惟明君子而後能知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":16,\"canonicalText\":\"故人心譬如槃水，正錯而勿動，則湛濁在下，而清明在上，則足以見鬒眉而察理矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":17,\"canonicalText\":\"微風過之，湛濁動乎下，清明亂於上，則不可以得大形之正也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":18,\"canonicalText\":\"心亦如是矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":19,\"canonicalText\":\"故導之以理，養之以清，物莫之傾，則足以定是非決嫌疑矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":20,\"canonicalText\":\"小物引之，則其正外易，其心內傾，則不足以決麤理矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":21,\"canonicalText\":\"故好書者眾矣，而倉頡獨傳者，壹也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":22,\"canonicalText\":\"好稼者眾矣，而后稷獨傳者，壹也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":23,\"canonicalText\":\"好樂者眾矣，而夔獨傳者，壹也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":24,\"canonicalText\":\"好義者眾矣，而舜獨傳者，壹也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":25,\"canonicalText\":\"倕作弓，浮游作矢，而羿精於射；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-26\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":26,\"canonicalText\":\"奚仲作車，乘杜作乘馬，而造父精於御：自古及今，未嘗有兩而能精者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-27\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":27,\"canonicalText\":\"曾子曰：「是其庭可以搏鼠，惡能與我歌矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-10_s-28\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-10\",\"order\":28,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":1,\"canonicalText\":\"空石之中有人焉，其名曰觙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":2,\"canonicalText\":\"其為人也，善射以好思。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":3,\"canonicalText\":\"耳目之欲接，則敗其思；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":4,\"canonicalText\":\"蚊虻之聲聞，則挫其精。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":5,\"canonicalText\":\"是以闢耳目之欲，而遠蚊虻之聲，閑居靜思則通。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":6,\"canonicalText\":\"思仁若是，可謂微乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":7,\"canonicalText\":\"孟子惡敗而出妻，可謂能自彊矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":8,\"canonicalText\":\"有子惡臥而焠掌，可謂能自忍矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":9,\"canonicalText\":\"未及好也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":10,\"canonicalText\":\"闢耳目之慾，可謂自彊矣，未及思也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":11,\"canonicalText\":\"蚊虻之聲聞則挫其精，可謂危矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":12,\"canonicalText\":\"未可謂微也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":13,\"canonicalText\":\"夫微者，至人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":14,\"canonicalText\":\"至人也，何彊？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":15,\"canonicalText\":\"何忍？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":16,\"canonicalText\":\"何危？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":17,\"canonicalText\":\"故濁明外景，清明內景，聖人縱其欲，兼其情，而制焉者理矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":18,\"canonicalText\":\"夫何彊？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":19,\"canonicalText\":\"何忍？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":20,\"canonicalText\":\"何危？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":21,\"canonicalText\":\"故仁者之行道也，無為也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":22,\"canonicalText\":\"聖人之行道也，無彊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":23,\"canonicalText\":\"仁者之思也恭，聖者之思也樂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-11_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-11\",\"order\":24,\"canonicalText\":\"此治心之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":1,\"canonicalText\":\"凡觀物有疑，中心不定，則外物不清。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":2,\"canonicalText\":\"吾慮不清，未可定然否也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":3,\"canonicalText\":\"冥冥而行者，見寢石以為伏虎也，見植林以為後人也：冥冥蔽其明也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":4,\"canonicalText\":\"醉者越百步之溝，以為蹞步之澮也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":5,\"canonicalText\":\"俯而出城門，以為小之閨也：酒亂其神也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":6,\"canonicalText\":\"厭目而視者，視一為兩；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":7,\"canonicalText\":\"掩耳而聽者，聽漠漠而以為哅哅：埶亂其官也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":8,\"canonicalText\":\"故從山上望牛者若羊，而求羊者不下牽也：遠蔽其大也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":9,\"canonicalText\":\"從山下望木者，十仞之木若箸，而求箸者不上折也：高蔽其長也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":10,\"canonicalText\":\"水動而景搖，人不以定美惡：水埶玄也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":11,\"canonicalText\":\"瞽者仰視而不見星，人不以定有無：用精惑也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":12,\"canonicalText\":\"有人焉以此時定物，則世之愚者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":13,\"canonicalText\":\"彼愚者之定物，以疑決疑，決必不當。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-12_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-12\",\"order\":14,\"canonicalText\":\"夫苟不當，安能無過乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":1,\"canonicalText\":\"夏首之南有人焉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":2,\"canonicalText\":\"曰涓蜀梁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":3,\"canonicalText\":\"其為人也，愚而善畏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":4,\"canonicalText\":\"明月而宵行，俯見其影，以為伏鬼也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":5,\"canonicalText\":\"仰視其髮，以為立魅也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":6,\"canonicalText\":\"背而走，比至其家，失氣而死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":7,\"canonicalText\":\"豈不哀哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":8,\"canonicalText\":\"凡人之有鬼也，必以其感忽之間，疑玄之時定1之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":9,\"canonicalText\":\"此人之所以無有而有無之時也，而己以定事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":10,\"canonicalText\":\"故傷於濕而痺，痺而擊鼓烹豚，則必有敝鼓喪豚之費矣，而未有俞疾之福也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-13_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-13\",\"order\":11,\"canonicalText\":\"故雖不在夏首之南，則無以異矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":1,\"canonicalText\":\"凡以知，人之性也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":2,\"canonicalText\":\"可以知，物之理也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":3,\"canonicalText\":\"以可以知人之性，求可以知物之理，而無所疑止之，則沒世窮年不能徧也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":4,\"canonicalText\":\"其所以貫理焉雖億萬，已不足浹萬物之變，與愚者若一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":5,\"canonicalText\":\"學、老身長子，而與愚者若一，猶不知錯，夫是之謂妄人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":6,\"canonicalText\":\"故學也者，固學止之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":7,\"canonicalText\":\"惡乎止之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":8,\"canonicalText\":\"曰：止諸至足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":9,\"canonicalText\":\"曷謂至足？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":10,\"canonicalText\":\"曰：聖王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":11,\"canonicalText\":\"聖也者，盡倫者也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":12,\"canonicalText\":\"王也者，盡制者也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":13,\"canonicalText\":\"兩盡者，足以為天下極矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":14,\"canonicalText\":\"故學者以聖王為師，案以聖王之制為法，法其法以求其統類，以務象效其人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":15,\"canonicalText\":\"嚮是而務，士也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":16,\"canonicalText\":\"類是而幾，君子也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":17,\"canonicalText\":\"知之，聖人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":18,\"canonicalText\":\"故有知非以慮是，則謂之懼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":19,\"canonicalText\":\"有勇非以持是，則謂之賊；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":20,\"canonicalText\":\"察孰非以分是，則謂之篡；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":21,\"canonicalText\":\"多能非以脩蕩是，則謂之知；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":22,\"canonicalText\":\"辯利非以言是，則謂之詍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-23\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":23,\"canonicalText\":\"傳曰：「天下有二：非察是，是察非。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-24\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":24,\"canonicalText\":\"」謂合王制不合王制也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-14_s-25\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-14\",\"order\":25,\"canonicalText\":\"天下有不以是為隆正也，然而猶有能分是非、治曲直者邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-15_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-15\",\"order\":1,\"canonicalText\":\"若夫非分是非，非治曲直，非辨治亂，非治人道，雖能之無益於人，不能無損於人；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-15_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-15\",\"order\":2,\"canonicalText\":\"案直將治怪說，玩奇辭，以相撓滑也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-15_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-15\",\"order\":3,\"canonicalText\":\"案彊鉗而利口，厚顏而忍詬，無正而恣睢，妄辨而幾利；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-15_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-15\",\"order\":4,\"canonicalText\":\"不好辭讓，不敬禮節，而好相推擠：此亂世姦人之說也，則天下之治說者，方多然矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-15_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-15\",\"order\":5,\"canonicalText\":\"傳曰：「析辭而為察，言物而為辨，君子賤之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-15_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-15\",\"order\":6,\"canonicalText\":\"博聞彊志，不合王制，君子賤之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-15_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-15\",\"order\":7,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-16_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-16\",\"order\":1,\"canonicalText\":\"為之無益於成也，求之無益於得也，憂戚之無益於幾也，則廣焉能棄之矣，不以自妨也，不少頃幹之胸中。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-16_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-16\",\"order\":2,\"canonicalText\":\"不慕往，不閔來，無邑憐之心，當時則動，物至而應，事起而辨，治亂可否，昭然明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":1,\"canonicalText\":\"周而成，泄而敗，明君無之有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":2,\"canonicalText\":\"宣而成，隱而敗，闇君無之有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":3,\"canonicalText\":\"故人君者，周則讒言至矣，直言反矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":4,\"canonicalText\":\"小人邇而君子遠矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":5,\"canonicalText\":\"《詩》雲：「墨以為明，狐狸而蒼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":6,\"canonicalText\":\"」此言上幽而下險也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":7,\"canonicalText\":\"君人者，宣則直言至矣，而讒言反矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":8,\"canonicalText\":\"君子邇而小人遠矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":9,\"canonicalText\":\"《詩》雲：「明明在下，赫赫在上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-21_p-17_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-21\",\"passageId\":\"xunzi_ch-21_p-17\",\"order\":10,\"canonicalText\":\"」此言上明而下化也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
